1	// A scenario the claim office refuses to process: the input is well-formed
2	// enough to read, but breaks a rule of the domain (an item type nobody insures,
3	// a claim against a step that never issued a policy). Distinct from a
4	// TypeError or any other bug in this module — the CLI must report a rejection
5	// as an error description and a non-zero exit, whereas a bug is a bug. Catching
6	// this type, rather than every throwable, is what keeps the two apart.
7	export class ClaimOfficeError extends Error {
8	  constructor(message: string) {
9	    super(message);
10	    this.name = "ClaimOfficeError";
11	  }
12	}
13	
14	export type QuoteResult = { premium: number };
15	
16	export type ClaimResult = { payout: number; remainingCap: number };
17	
18	export type StepResult = QuoteResult | ClaimResult;
19	
20	export type ScenarioResults = { results: StepResult[] };
21	
22	const PROCESSING_FEE = 5;
23	
24	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
25	
26	const LOYALTY_DISCOUNT_RATE = 0.2;
27	
28	const LOYALTY_THRESHOLD_YEARS = 2;
29	
30	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
31	
32	// One catalogue entry per insurable item type. Premium and insurance value are
33	// two facts about the same thing, so they live together: an item type either is
34	// in the catalogue with both, or is unknown.
35	type CatalogueEntry = { basePremium: number; insuranceValue: number };
36	
37	const ITEM_CATALOGUE: Record<string, CatalogueEntry> = {
38	  sword: { basePremium: 100, insuranceValue: 1000 },
39	  amulet: { basePremium: 60, insuranceValue: 600 },
40	  staff: { basePremium: 80, insuranceValue: 800 },
41	  potion: { basePremium: 40, insuranceValue: 400 },
42	  rune: { basePremium: 25, insuranceValue: 250 },
43	  moonstone: { basePremium: 25, insuranceValue: 250 },
44	};
45	
46	// The catalogue is the single place that decides whether an item type exists,
47	// so an unknown type fails here, by name, rather than as a stray TypeError
48	// somewhere downstream.
49	const catalogueEntryOf = (type: string): CatalogueEntry => {
50	  const entry = ITEM_CATALOGUE[type];
51	  if (entry === undefined) {
52	    throw new ClaimOfficeError(`Unknown item type: ${type}`);
53	  }
54	  return entry;
55	};
56	
57	const basePremiumOf = (type: string): number =>
58	  catalogueEntryOf(type).basePremium;
59	
60	const insuranceValueOf = (type: string): number =>
61	  catalogueEntryOf(type).insuranceValue;
62	
63	type Item = { type: string; cursed?: boolean; enchantment?: number };
64	
65	// Steps are discriminated by `op`: a quote carries the items to insure, a claim
66	// carries damage entries against a policy an earlier quote step created.
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type Incident = { cause: string; damages: Damage[] };
72	
73	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
74	
75	type Step = QuoteStep | ClaimStep;
76	
77	// Scenarios arrive as parsed JSON (from the CLI, and from object literals in
78	// the spec whose `op` widens to `string`), so the boundary type is deliberately
79	// wider than `Step`. Narrowing happens once, in `runStep`.
80	type StepInput = {
81	  op: string;
82	  items?: Item[];
83	  policy?: number;
84	  incident?: Incident;
85	};
86	
87	const isQuoteStep = (step: StepInput): step is QuoteStep =>
88	  step.op === "quote" && step.items !== undefined;
89	
90	const isClaimStep = (step: StepInput): step is ClaimStep =>
91	  step.op === "claim" && step.incident !== undefined && step.policy !== undefined;
92	
93	type Customer = { yearsWithMHPCO: number };
94	
95	type Scenario = { customer: Customer; steps: StepInput[] };
96	
97	const BLOCK_SIZE = 3;
98	
99	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
100	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
101	// a block either — "alike" means the same type, not the same family.
102	const BLOCK_BASE_PREMIUM = 60;
103	
104	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
105	
106	const countByType = (items: Item[]): Map<string, number> =>
107	  items.reduce(
108	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
109	    new Map<string, number>(),
110	  );
111	
112	const isBlock = (type: string, count: number): boolean =>
113	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
114	
115	const groupBasePremium = (type: string, count: number): number =>
116	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * basePremiumOf(type);
117	
118	const sum = (numbers: number[]): number =>
119	  numbers.reduce((total, value) => total + value, 0);
120	
121	const policyBasePremium = (items: Item[]): number =>
122	  sum(
123	    [...countByType(items)].map(([type, count]) =>
124	      groupBasePremium(type, count),
125	    ),
126	  );
127	
128	const CURSE_SURCHARGE_RATE = 0.5;
129	
130	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
131	
132	const HIGH_ENCHANTMENT_THRESHOLD = 5;
133	
134	const isCursed = (item: Item): boolean => item.cursed === true;
135	
136	const isHighlyEnchanted = (item: Item): boolean =>
137	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
138	
139	// Both surcharges can apply to the same item, so the rates add.
140	const itemSurchargeRate = (item: Item): number =>
141	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
142	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
143	
144	// Item-specific modifiers apply to the affected item's own base premium, not to
145	// the policy total — note that is the *ungrouped* base premium, so a cursed
146	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
147	const policyItemSurchargeTotal = (items: Item[]): number =>
148	  sum(
149	    items.map((item) => basePremiumOf(item.type) * itemSurchargeRate(item)),
150	  );
151	
152	const isLoyal = (customer: Customer): boolean =>
153	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
154	
155	// Policy-wide rates are summed rather than compounded, so a loyal customer's
156	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
157	// Every quote after the customer's first is a follow-up contract; the
158	// first-insurance surcharge still applies to it, since each item in a quote is
159	// treated as a first insurance regardless of customer history.
160	const policyModifierRate = (customer: Customer, isFollowUp: boolean): number =>
161	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
162	  (isFollowUp ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0) +
163	  FIRST_INSURANCE_SURCHARGE_RATE;
164	
165	const priceQuote = (
166	  step: QuoteStep,
167	  customer: Customer,
168	  isFollowUp: boolean,
169	): QuoteResult => {
170	  // Every modifier is a percentage of an *unmodified* base and they are all
171	  // summed, never compounded. Item surcharges are percentages of the affected
172	  // item's own base premium; policy-wide modifiers are percentages of the
173	  // policy base premium, which excludes those item surcharges. Summing the
174	  // rates before multiplying also keeps binary floating point out of trouble:
175	  // a compounded `base * (1 + rate)` chain drifts by ~1e-14, and Math.ceil
176	  // would turn that into a whole extra gold piece.
177	  const policyBase = policyBasePremium(step.items);
178	  const premiumBeforeFee =
179	    policyBase +
180	    policyItemSurchargeTotal(step.items) +
181	    policyBase * policyModifierRate(customer, isFollowUp);
182	
183	  // The fee is added after every percentage modifier, and only the final
184	  // premium is rounded — intermediates stay fractional.
185	  return { premium: Math.ceil(premiumBeforeFee + PROCESSING_FEE) };
186	};
187	
188	// A quote is a follow-up contract when the customer already holds one, i.e.
189	// when an earlier step in this scenario was itself a quote. Preceding claim
190	// steps do not make the next quote a follow-up.
191	const isFollowUpContract = (steps: StepInput[], index: number): boolean =>
192	  steps.slice(0, index).some(isQuoteStep);
193	
194	const DEDUCTIBLE_PER_DAMAGE = 100;
195	
196	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
197	
198	// The insurance sum is the plain sum of the items' insurance values; the block
199	// discount applies to the premium only, never to the sum insured.
200	const insuranceSum = (items: Item[]): number =>
201	  sum(items.map((item) => insuranceValueOf(item.type)));
202	
203	// A policy pays out at most twice its insurance sum over its lifetime.
204	const policyCap = (items: Item[]): number =>
205	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items);
206	
207	// Distinct from the premium-side high-enchantment *surcharge*, whose threshold
208	// is 5: this is a different rule that happens to key off the same attribute.
209	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
210	
211	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
212	
213	const FULL_REIMBURSEMENT_RATE = 1;
214	
215	const hasHighEnchantmentReimbursement = (item: Item): boolean =>
216	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD;
217	
218	// Each clause states the share of the damage it will reimburse; an item that
219	// trips no clause is reimbursed in full.
220	//
221	// The spec's second reimbursement clause — "damage to items made of dragon
222	// material is fully reimbursed" — is deliberately absent, not forgotten. It is
223	// unobservable here, on two counts:
224	//
225	//   1. It reimburses at FULL_REIMBURSEMENT_RATE, which is already the rate for
226	//      an item that trips no clause at all. On its own it changes nothing.
227	//   2. Where it competes with the high-enchantment clause, the spec says the
228	//      50 % rule wins (enchantment 9 + dragon → 400 G, same as enchantment 9
229	//      alone). So it cannot win a conflict either.
230	//
231	// No input the spec describes distinguishes an implementation with a dragon
232	// branch from this one, so `material` is not a field on `Item`. This stops
233	// holding the moment full reimbursement stops being the default — e.g. if a
234	// policy-wide co-payment is introduced — at which point the clause becomes
235	// observable and must be implemented.
236	const reimbursementRate = (item: Item): number =>
237	  hasHighEnchantmentReimbursement(item)
238	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
239	    : FULL_REIMBURSEMENT_RATE;
240	
241	// A reimbursement clause reduces the damage amount; the deductible comes off
242	// whatever the clause leaves.
243	// A damage is something the office pays out against; a negative one would have
244	// the customer owing the office, which the price list has no notion of.
245	const validateDamageAmount = (damage: Damage): void => {
246	  if (damage.amount < 0) {
247	    throw new ClaimOfficeError(
248	      `Damage amount cannot be negative: ${damage.amount}`,
249	    );
250	  }
251	};
252	
253	const damagePayout = (damage: Damage, item: Item): number =>
254	  damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE;
255	
256	// A damage entry carries no identity beyond its type, so it is settled against
257	// any insured item of that type — and it consumes that item, so a second
258	// damage entry of the same type must find a second insured item. The pool is
259	// what is left to settle against: each match takes its item out of it.
260	type ItemPool = ReadonlyMap<string, Item[]>;
261	
262	const poolOf = (items: Item[]): ItemPool =>
263	  items.reduce(
264	    (pool, item) => pool.set(item.type, [...(pool.get(item.type) ?? []), item]),
265	    new Map<string, Item[]>(),
266	  );
267	
268	// A policy only covers what it insures, so a damage entry naming an item the
269	// policy does not carry — or one more of a type than it carries — is a
270	// rejection rather than a zero-value payout.
271	//
272	// This subsumes the unknown-item-type case, and deliberately so: the claim path
273	// never consults ITEM_CATALOGUE. Coverage is the stronger check — a policy can
274	// only hold items that passed `catalogueEntryOf` when it was quoted, so a type
275	// nobody insures is necessarily absent from the pool and is rejected here, by
276	// name. Adding a catalogue lookup on this path would be dead code: it could
277	// only fire on inputs that this lookup already rejects, and it would report the
278	// weaker of the two reasons ("unknown type" when the actionable fact is that
279	// the policy does not cover it).
280	const takeInsuredItem = (
281	  pool: ItemPool,
282	  itemType: string,
283	): { item: Item; remaining: ItemPool } => {
284	  const [item, ...rest] = pool.get(itemType) ?? [];
285	  if (item === undefined) {
286	    throw new ClaimOfficeError(
287	      `Damaged item is not covered by the policy: ${itemType}`,
288	    );
289	  }
290	  return { item, remaining: new Map(pool).set(itemType, rest) };
291	};
292	
293	// One pass over the damages, drawing down the pool as it goes: the nth damage
294	// of a type meets the nth insured item of that type, and running out is a
295	// rejection. Pairing them up front is what keeps `incidentPayout` a plain sum.
296	const matchDamagesToItems = (
297	  damages: Damage[],
298	  policyItems: Item[],
299	): { damage: Damage; item: Item }[] =>
300	  damages.reduce<{ matches: { damage: Damage; item: Item }[]; pool: ItemPool }>(
301	    ({ matches, pool }, damage) => {
302	      validateDamageAmount(damage);
303	      const { item, remaining } = takeInsuredItem(pool, damage.itemType);
304	
305	      return { matches: [...matches, { damage, item }], pool: remaining };
306	    },
307	    { matches: [], pool: poolOf(policyItems) },
308	  ).matches;
309	
310	// The deductible applies once per damaged item, so each damage entry is
311	// reduced separately before the entries are summed. A damage entry names its
312	// item by type, so the clauses are read off the insured item it was matched to.
313	const incidentPayout = (incident: Incident, policyItems: Item[]): number =>
314	  Math.floor(
315	    sum(
316	      matchDamagesToItems(incident.damages, policyItems).map(
317	        ({ damage, item }) => damagePayout(damage, item),
318	      ),
319	    ),
320	  );
321	
322	// The cap is a lifetime budget for the policy, so a claim can pay out only what
323	// earlier claims against the same policy have left of it.
324	const settleClaim = (
325	  step: ClaimStep,
326	  policyItems: Item[],
327	  alreadyPaidOut: number,
328	): ClaimResult => {
329	  const remainingBefore = policyCap(policyItems) - alreadyPaidOut;
330	  const payout = Math.min(
331	    incidentPayout(step.incident, policyItems),
332	    remainingBefore,
333	  );
334	
335	  return { payout, remainingCap: remainingBefore - payout };
336	};
337	
338	const quoteStepAt = (steps: StepInput[], index: number): QuoteStep => {
339	  // `policy` is a step number in the scenario, so it indexes the full step
340	  // list — not a prefix of it.
341	  const step = steps[index];
342	  if (step === undefined || !isQuoteStep(step)) {
343	    throw new ClaimOfficeError(
344	      `Claim references a step that is not a quote: ${index}`,
345	    );
346	  }
347	  return step;
348	};
349	
350	// The payouts made so far against each policy, keyed by the step index of the
351	// quote that created it. Claims consume their policy's cap as the scenario
352	// runs, so this has to be carried from each step to the next.
353	type PaidOutByPolicy = ReadonlyMap<number, number>;
354	
355	const paidOutOn = (paidOut: PaidOutByPolicy, policy: number): number =>
356	  paidOut.get(policy) ?? 0;
357	
358	const withPayoutRecorded = (
359	  paidOut: PaidOutByPolicy,
360	  policy: number,
361	  payout: number,
362	): PaidOutByPolicy =>
363	  new Map(paidOut).set(policy, paidOutOn(paidOut, policy) + payout);
364	
365	// Running a step yields its result *and* the cap ledger the next step must see.
366	// Pairing them is what lets a claim hand on the payout it just consumed without
367	// the caller having to re-derive the step's kind from its result.
368	type StepOutcome = { result: StepResult; paidOut: PaidOutByPolicy };
369	
370	const runStep = (
371	  step: StepInput,
372	  customer: Customer,
373	  steps: StepInput[],
374	  index: number,
375	  paidOut: PaidOutByPolicy,
376	): StepOutcome => {
377	  if (isQuoteStep(step)) {
378	    // A quote consumes no cap, so it passes the ledger on untouched.
379	    return {
380	      result: priceQuote(step, customer, isFollowUpContract(steps, index)),
381	      paidOut,
382	    };
383	  }
384	  if (isClaimStep(step)) {
385	    const result = settleClaim(
386	      step,
387	      quoteStepAt(steps, step.policy).items,
388	      paidOutOn(paidOut, step.policy),
389	    );
390	
391	    return {
392	      result,
393	      paidOut: withPayoutRecorded(paidOut, step.policy, result.payout),
394	    };
395	  }
396	  throw new ClaimOfficeError(`Unsupported step op: ${step.op}`);
397	};
398	
399	// What the fold carries from step to step: the results so far, plus the cap
400	// ledger. Only `results` is part of the answer — `paidOut` is scaffolding, so
401	// this is deliberately not `ScenarioResults`.
402	type ScenarioProgress = {
403	  results: StepResult[];
404	  paidOut: PaidOutByPolicy;
405	};
406	
407	export const runScenario = (scenario: Scenario): ScenarioResults => {
408	  const { results } = scenario.steps.reduce<ScenarioProgress>(
409	    ({ results, paidOut }, step, index) => {
410	      const outcome = runStep(
411	        step,
412	        scenario.customer,
413	        scenario.steps,
414	        index,
415	        paidOut,
416	      );
417	
418	      return {
419	        results: [...results, outcome.result],
420	        paidOut: outcome.paidOut,
421	      };
422	    },
423	    { results: [], paidOut: new Map() },
424	  );
425	
426	  return { results };
427	};
